-- 📚 꼭집 주거 사전 — 출산자녀 자산 가산 3.79억·4,996만 / 4.13억·5,451만 · 국민·행복 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 2.1초 · 결과:
-- {"p1": 9, "p2": 9, "by_std": {"국민임대": 5, "매입임대": 1, "행복주택": 3}, "ex": ["20652_1_서울특별시_영등포구", "2015122300020701", "2015122300020527", "2015122300020328"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x order by x.announcement_id,(x.source='LH')desc,x.created_at desc),e as(select distinct ec.announcement_id,coalesce(m.std_type,ec.housing_type)std,ec.asset_limit,ec.car_limit from eligibility_criteria ec join a on a.announcement_id=ec.announcement_id and a.yr=2026 left join housing_type_map m on m.source_table='eligibility_criteria' and m.housing_type=ec.housing_type where ec.announcement_id is not null)select json_build_object('p1',(select count(distinct announcement_id) from e where asset_limit=379000000 and car_limit=49960000),'p2',(select count(distinct announcement_id) from e where asset_limit=413000000 and car_limit=54510000),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from e where asset_limit in(379000000,413000000) group by 1)q),'ex',(select json_agg(i) from(select distinct announcement_id i from e where asset_limit=413000000 order by 1 desc limit 4)q))j;
